    uSTEP_LOAD_EN: in std_logic;
    uSTEP_LOAD: in std_logic_vector(5 downto 0);
    JUMP_SEL: in std_logic;
    COND_CHECKER_OUT: in std_logic;
    uSTEP: out std_logic_vector(5 downto 0));
end MICROSTEP_COUNTER;

architecture Behavioral of MICROSTEP_COUNTER is
  signal s0: std_logic;
begin
  s0 <= (JUMP_SEL OR (uSTEP_LOAD_EN AND COND_CHECKER_OUT));
  gate0: entity work.DIG_CounterPreset -- uSTEP_COUNTER
    generic map (
      Bits => 6,
      maxValue => 0)
    port map (
      en => '1',
      C => CPU_CLK,
      dir => '0',
      p_in => uSTEP_LOAD,
      ld => s0,
      clr => uSTEP_RESET,
      p_out => uSTEP);
end Behavioral;

