entity SPECIAL_DIV is
  port (
    N: in std_logic;
    OPCODE: in std_logic_vector(5 downto 0);
    uSTEP_RESET: in std_logic;
    uSTEP: in std_logic_vector(5 downto 0);
    CLK: in std_logic;
    DIV_CTRL: out std_logic;
    DIV_RESULT: out std_logic_vector(15 downto 0));
end SPECIAL_DIV;

architecture Behavioral of SPECIAL_DIV is
  signal s0: std_logic_vector(15 downto 0);
  signal DIV_RESULT_temp: std_logic_vector(15 downto 0);
  signal s1: std_logic_vector(15 downto 0);
  signal s2: std_logic_vector(15 downto 0);
begin
  DIV_CTRL <= (N AND (OPCODE(0) AND NOT OPCODE(1) AND NOT OPCODE(2) AND OPCODE(3) AND NOT OPCODE(4) AND NOT OPCODE(5)));
  s0(0) <= (NOT uSTEP(0) AND NOT uSTEP(1) AND uSTEP(2) AND NOT uSTEP(3) AND NOT uSTEP(4) AND NOT uSTEP(5));
  s0(15 downto 1) <= "000000000000000";
  gate0: entity work.DIG_Add
    generic map (
      Bits => 16)
    port map (
      a => s0,
      b => DIV_RESULT_temp,
      c_i => '0',
      s => s1);
  gate1: entity work.MUX_GATE_BUS_1
    generic map (
      Bits => 16)
    port map (
      sel => uSTEP_RESET,
      in_0 => s1,
      in_1 => "0000000000000000",
      p_out => s2);
  gate2: entity work.DIG_Register_BUS -- DIV_RESULT
    generic map (
      Bits => 16)
    port map (
      D => s2,
      C => CLK,
      en => '1',
      Q => DIV_RESULT_temp);
  DIV_RESULT <= DIV_RESULT_temp;
end Behavioral;

