entity SPECIAL_MUL is
  port (
    Z: in std_logic;
    OPCODE: in std_logic_vector(5 downto 0);
    uSTEP_RESET: in std_logic;
    RA_BIT0: in std_logic;
    RB: in std_logic_vector(15 downto 0);
    CLK: in std_logic;
    uSTEP: in std_logic_vector(5 downto 0);
    MUL_CTRL: out std_logic;
    MUL_RESULT: out std_logic_vector(15 downto 0));
end SPECIAL_MUL;

architecture Behavioral of SPECIAL_MUL is
  signal s0: std_logic;
  signal s1: std_logic_vector(15 downto 0);
  signal MUL_RESULT_temp: std_logic_vector(15 downto 0);
  signal s2: std_logic_vector(15 downto 0);
  signal s3: std_logic_vector(15 downto 0);
begin
  MUL_CTRL <= ((Z AND (NOT OPCODE(0) AND NOT OPCODE(1) AND NOT OPCODE(2) AND OPCODE(3) AND NOT OPCODE(4) AND NOT OPCODE(5))) AND uSTEP_RESET);
  s0 <= ((uSTEP(0) AND uSTEP(1) AND NOT uSTEP(2) AND NOT uSTEP(3) AND NOT uSTEP(4) AND NOT uSTEP(5)) AND RA_BIT0);
  gate0: entity work.MUX_GATE_BUS_1
    generic map (
      Bits => 16)
    port map (
      sel => s0,
      in_0 => "0000000000000000",
      in_1 => RB,
      p_out => s1);
  gate1: entity work.DIG_Add
    generic map (
      Bits => 16)
    port map (
      a => s1,
      b => MUL_RESULT_temp,
      c_i => '0',
      s => s2);
  gate2: entity work.MUX_GATE_BUS_1
    generic map (
      Bits => 16)
    port map (
      sel => uSTEP_RESET,
      in_0 => s2,
      in_1 => "0000000000000000",
      p_out => s3);
  gate3: entity work.DIG_Register_BUS -- MUL_RESULT
    generic map (
      Bits => 16)
    port map (
      D => s3,
      C => CLK,
      en => '1',
      Q => MUL_RESULT_temp);
  MUL_RESULT <= MUL_RESULT_temp;
end Behavioral;

